using System;
using System.Threading.Tasks;
using NLog;
using FluentSeq;
using XTA.Core;
using XTA.Infrastructure.Data;
using XTA.Services;
using XTA.Services.TelegramService;

namespace XTA
{
    public class XTAStartupV2
    {
        private static readonly Logger nlog = LogManager.GetCurrentClassLogger();

        public static async Task RunAsync()
        {
            var ctx = XContext.Instance;

            var sequence = FluentSequence.Create("XTA_STARTUP")
                .Step("LoadConfig", () => {
                    // 1. 설정 로드 및 XParameter 초기화 로직 (기존 Initialize 코드 재활용)
                    ctx.Parameter = XTAStartup.Initialize();
                    return true;
                })
                .Step("InitDatabase", () => {
                    // 2. DB 서비스 생성 및 등록
                    var db = new XpoSqliteService(ctx.Parameter);
                    ctx.AddService(db);
                    ctx.AddService<ISignalRepository>(db);
                    return true;
                })
                .Step("RegisterServices", () => {
                    // 3. 핵심 서비스 조립 (Messenger 배제, 직접 주입)
                    ctx.AddService(new XGatewayService(ctx.Parameter));
                    ctx.AddService(new XSyncWorker(ctx.Parameter));
                    ctx.AddService(new XTelegram(ctx.Parameter));
                    return true;
                })
                .Step("StartServices", () => {
                    // 4. 서비스 일제 시작
                    ctx.Parameter.StartAll();
                    return true;
                })
                .OnFailure(err => {
                    nlog.Fatal($"[Startup] Failed at {err.StateName}: {err.Exception?.Message}");
                });

            await sequence.StartAsync();
        }

        /// <summary>
        /// 데이터 이관(Archive) 시퀀스 제안
        /// </summary>
        public static async Task ProcessTransferAsync()
        {
            var ctx = XContext.Instance;

            var transferSeq = FluentSequence.Create("DATA_TRANSFER")
                .Step("ScanClosedSignals", async () => {
                    // xe_status == Closed && xa_exit == XA_ACTIVE 인 것 찾기
                    return true; 
                })
                .Step("BackupToHistory", async () => {
                    // 복사 로직
                    return true;
                })
                .Step("DeleteOriginal", async () => {
                    // 삭제 로직
                    return true;
                })
                .OnSuccess(() => nlog.Info("[Transfer] Data migration completed successfully."))
                .Build();

            await transferSeq.StartAsync();
        }
    }
}

using XTA.Interfaces;
using XTA.Models;
using XTA.XData.Interfaces;

namespace XTA.Core
{
    /// <summary>
    /// XTA 시스템 전역 컨텍스트 및 서비스 컨테이너
    /// </summary>
    public class XContext
    {
        private static readonly Logger nlog = LogManager.GetCurrentClassLogger();
        private static readonly Lazy<XContext> _instance = new Lazy<XContext>(() => new XContext());
        public static XContext Instance => _instance.Value;

        private readonly ConcurrentDictionary<Type, object> _services = new ConcurrentDictionary<Type, object>();

        public XParameter Parameter { get; set; }
        public XConfig Config => Parameter?.Config;

        private XContext() { }

        // --- 서비스 등록 및 조회 (DI 대체) ---
        public void AddService<T>(T service) where T : class
        {
            _services[typeof(T)] = service;
            nlog.Trace($"[Context] Service registered: {typeof(T).Name}");
        }

        public T GetService<T>(Predicate<T> filter) where T : class
        {
            if (Parameter != null) return Parameter.GetService<T>(filter);

            foreach (var service in _services.Values)
            {
                if (service is T t && filter(t)) return t;
            }

            return null;
        }

        // --- 헬퍼 속성들 ---
        public ISignalRepository SignalRepo => GetService<ISignalRepository>();
        public IXGatewayService Gateway => GetService<IXGatewayService>();
        public ISoundService Sound => GetService<ISoundService>();
        public IDataService Data => GetService<IDataService>();
        // 추가적인 핵심 서비스들을 속성으로 노출하여 코드 가독성 향상
    }
}

using NLog;
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;

namespace XTA.Models
{
    /// <summary>
    /// 시스템 전역 파라미터 및 서비스 로케이터.
    /// [Thread-Safe] 모든 서비스 및 채널 관리에 Concurrent 컬렉션을 사용함.
    /// </summary>
    public class XParameter
    {
        public NLog.ILogger nlog { get; set; } = NLog.LogManager.GetCurrentClassLogger();
        public XConfig Config { get; set; } = new();
        private readonly ConcurrentBag<XObject> _services = new ConcurrentBag<XObject>();
        public readonly ConcurrentDictionary<long, XChannelInfo> Channels = new ConcurrentDictionary<long, XChannelInfo>();
        public readonly ConcurrentDictionary<int, XChannelOption> ChannelOptions = new ConcurrentDictionary<int, XChannelOption>();

        public XParameter()
        {
            try
            {
                // NLog 설정 최적화 및 기동 안전성 확보
                string baseDir = AppDomain.CurrentDomain.BaseDirectory;
                string configPath = System.IO.Path.Combine(baseDir, "NLog.config");

                if (System.IO.File.Exists(configPath))
                {
                    LogManager.Configuration = new NLog.Config.XmlLoggingConfiguration(configPath);
                    LogManager.ReconfigExistingLoggers();
                }
                else
                {
                    var config = new NLog.Config.LoggingConfiguration();
                    var consoleTarget = new NLog.Targets.ConsoleTarget("console");
                    config.AddRule(LogLevel.Trace, LogLevel.Fatal, consoleTarget);
                    LogManager.Configuration = config;
                }

                nlog = LogManager.GetCurrentClassLogger();
                nlog.Info($"[XParameter] NLog system initialized. Config path: {configPath}");
            }
            catch (Exception ex)
            {
                Console.WriteLine($"[FATAL] NLog initialization failed: {ex.Message}");
            }
        }

        public void Add(XObject service)
        {
            _services.Add(service);
            nlog?.Trace($"[ServiceRegistered] {service.GetType().Name}");
        }

        public void Add<T>(T service) where T : class
        {
            if (service is XObject xobj) Add(xobj);
        }

        public void StartAll()
        {
            nlog?.Trace($"[ServicesStarting] Attempting to start {_services.Count} services...");
            foreach (var service in _services)
            {
                try
                {
                    nlog?.Trace($"[Service:Start:Begin] {service.GetType().Name} (cid: {service.CID})");
                    service.Start();
                    nlog?.Trace($"[Service:Start:End] {service.GetType().Name} - SUCCESS");
                }
                catch (Exception ex)
                {
                    nlog?.Error(ex, $"[Service:Start:Error] {service.GetType().Name} - FAILED");
                }
            }
            nlog?.Trace("[ServicesStarted] All registered services have been processed.");
        }

        public void StopAll()
        {
            foreach (var service in _services)
            {
                service.Stop();
            }
            nlog?.Trace("[ServicesStopped] All registered services have been stopped.");
        }

        public T? GetService<T>() where T : class
        {
            return _services.OfType<T>().FirstOrDefault();
        }

        public T? GetService<T>(Predicate<T> filter) where T : class
        {
            return _services.OfType<T>().FirstOrDefault(t => filter(t));
        }

        public void RegisterChannel(XChannelInfo info)
        {
            if (info == null) return;
            Channels.TryAdd(info.CID, info);
            nlog?.Trace($"[ChannelRegistered] ID:{info.CID} | CNO:{info.CNO} | Name:{info.Name} | Type:{info.Type}");
        }

        public XChannelInfo? GetChannel(long channelId)
        {
            return Channels.TryGetValue(channelId, out var info) ? info : null;
        }

        public XChannelInfo? GetChannelByCno(int cno)
        {
            return Channels.Values.FirstOrDefault(c => c.CNO == cno);
        }
    }
}

using NLog;
using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using XTA.Channels.GG;
using XTA.Channels.GMK;

using XTA.Infrastructure.Data;
using XTA.Models;
using XTA.Services;
using XTA.Services.TelegramService;
using XTA.XData.Interfaces;
using XTA.XData.Models;

namespace XTA
{
    /// <summary>
    /// XTG 시스템을 초기화 및 서비스를 구성하는 스타트업 클래스
    /// </summary>
    public class XTAStartup
    {
        private static Logger nlog => LogManager.GetCurrentClassLogger();

        /// <summary>
        /// 설정 파일을 로드하여 XParameter 및 서비스들을 초기화합니다.
        /// </summary>
        /// <param name="configPath">XConfig JSON 파일 경로 (기본값: _config/ASTA.json)</param>
        /// <returns>초기화된 XParameter 객체</returns>
        public static XParameter Initialize(string configPath = "_config/ASTA.json")
        {
            // [Fix] 인코딩 프로바이더 등록 (CP949 등 지원)
            System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

            // [Fix] 로그 파일 강제 초기화
            string logPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "_log", "XTA_Active.log");
            if (File.Exists(logPath))
            {
                try { File.Delete(logPath); }
                catch { /* 무시 */ }
            }

            var logger = nlog;
            logger.Info($"[Startup] ************************************ {configPath}");
            logger.Info($"[Startup] Initializing XTA System with config: {configPath}");


            // 1. 설정 파일 존재 여부 확인 및 자동 생성
            EnsureConfigFile(configPath);

            // 2. 설정 로드
            XConfig? config = null;
            try
            {
                string json = File.ReadAllText(configPath);
                config = JsonSerializer.Deserialize<XConfig>(json);
            }
            catch (Exception ex)
            {
                nlog.Error(ex, $"[Startup] Failed to load config from {configPath}");
            }

            if (config == null)
            {
                nlog.Fatal("[Startup] Config object is null. Initialization aborted.");
                throw new InvalidOperationException("Config load failed.");
            }

            // 3. XParameter 생성 및 설정 주입
            var param = new XParameter
            {
                Config = config
            };

            // 4. 서비스 및 채널 초기화
            ConfigureServices(param, config);

            nlog.Trace("[Startup] XTA System initialization completed.");
            return param;
        }
        private static void ConfigureServices(XParameter param, XConfig config)
        {
            nlog.Trace("[Startup] Configuring Services and Channels from Config (Dynamic)...");

            // 1. 설정된 모든 채널을 순회하며 인터프리터 동적 생성
            foreach (var entry in config.Channels)
            {
                var info = entry.Value;
                if (info.CNO == 0)
                {
                    param.RegisterChannel(info);
                    continue;
                }

                // Plugin.ClassName이 지정된 경우에만 인터프리터 인스턴스 생성
                if (!string.IsNullOrEmpty(info.Plugin.ClassName))
                {
                    try
                    {
                        // 클래스이름으로 전체 타입 경로를 추론 (네임스페이스 포함)
                        string fullTypeName = info.Plugin.ClassName.Contains(".")
                            ? info.Plugin.ClassName
                            : FindFullTypeName(info.Plugin.ClassName);

                        Type? type = Type.GetType(fullTypeName);
                        if (type == null)
                        {
                            // AssemblyName이 지정되어 있다면 해당 어셈블리에서 찾아 시도
                            if (!string.IsNullOrEmpty(info.Plugin.AssemblyName))
                            {
                                fullTypeName = $"{fullTypeName}, {info.Plugin.AssemblyName}";
                                type = Type.GetType(fullTypeName);
                            }
                        }

                        if (type != null)
                        {
                            var interpreter = Activator.CreateInstance(type, param, info) as XObject;
                            if (interpreter != null)
                            {
                                param.Add(interpreter);
                                nlog.Trace($"[Startup] Dynamically loaded interpreter: {fullTypeName} for CNO {info.CNO}");
                            }
                        }
                        else
                        {
                            nlog.Error($"[Startup] Could not find type: {fullTypeName}");
                        }
                    }
                    catch (Exception ex)
                    {
                        nlog.Error(ex, $"[Startup] Failed to instantiate interpreter for {info.Name} (CNO: {info.CNO})");
                    }
                }
                else
                {
                    nlog.Trace($"[Startup] No ClassName defined for CNO {info.CNO} ({info.Name}). Skipping interpreter registration.");
                }

                param.RegisterChannel(info);
            }

            // 2. 핵심 서비스 등록
            var db = new XpoSqliteService(param);
            param.Add(db);
            param.Add<ISignalRepository>(db);
            param.Add<IChannelOptionRepository>(db);
            param.Add<IGridProfileRepository>(db);

            param.Add(new XGatewayService(param));
            param.Add(new XSyncWorker(param));
            param.Add(new XTelegram(param));

            // [v1.1] StartAll()은 외부에서 명시적으로 호출하도록 분리 (Extension Service 등록 기회 제공)
            // param.StartAll();

            // 3. 설정값(JSON) 기반으로 DB 캐시(Options/Profiles) 초기화
            LoadOptionsFromConfig(param, config);
        }

        /// <summary>
        /// 모든 등록된 서비스를 시작합니다. (Extension 서비스 등록 후 최종 호출 권장)
        /// </summary>
        public static void Start(XParameter param)
        {
            nlog.Trace("[Startup] Starting all registered services...");
            param.StartAll();

            // [Phase 2] 앱 재시작 시 티켓-SID 매핑 캐시 재구축
            try
            {
                var repo = param.GetService<ISignalRepository>();
                if (repo != null)
                {
                    // 비동기 실행을 위해 Task.Run 사용 (UI 스레드 차단 방지)
                    Task.Run(async () =>
                    {
                        var activeSignals = await repo.GetAllActiveSignalsAsync();
                        XTradeManager.Instance.Initialize(activeSignals);
                        nlog.Info($"[Startup] Rebuilt XTradeManager ticket-SID mapping cache: {activeSignals.Count} signals loaded.");
                    });
                }
            }
            catch (Exception ex)
            {
                nlog.Error(ex, "[Startup] Failed to rebuild XTradeManager mapping cache.");
            }
        }

        /// <summary>
        /// [v1.1] 런타임에 설정을 재로드하고 DB와 동기화합니다. (Hot-Reload)
        /// </summary>
        public static void ReloadConfig(XParameter param, string configPath)
        {
            try
            {
                nlog.Info($"[Startup:Reload] Hot-reloading configuration from {configPath}");

                if (!File.Exists(configPath)) return;

                string json = File.ReadAllText(configPath);
                var newConfig = JsonSerializer.Deserialize<XConfig>(json);

                if (newConfig != null)
                {
                    // 1. 메모리 객체 교체
                    param.Config = newConfig;

                    // 2. DB 동기화 (TradingOptions, Profiles)
                    LoadOptionsFromConfig(param, newConfig);

                    nlog.Info("[Startup:Reload] Configuration successfully reloaded and synchronized to DB.");
                }
            }
            catch (Exception ex)
            {
                nlog.Error(ex, "[Startup:Reload] Failed to reload configuration.");
            }
        }

        private static void LoadOptionsFromConfig(XParameter param, XConfig config)
        {
            var db = param.GetService<XpoSqliteService>();
            if (db == null) return;

            nlog.Trace("[Startup] Synchronizing ChannelOptions and GridProfiles from Config to DB (Overwrite Mode)...");

            foreach (var entry in config.Channels)
            {
                var info = entry.Value;

                // 구매/판매 옵션이 없으면 스킵
                if (info.BuyOption == null && info.SellOption == null) continue;

                // [동기화] 설정의 구매/판매 옵션
                nlog.Trace($"[Startup] Syncing Option for CNO:{info.CNO} ({info.Name}) | BuyEnable:{info.BuyOption?.Enable}, SellEnable:{info.SellOption?.Enable}");

                var channelOpt = new XTA.XData.Models.XChannelOption
                {
                    cno = info.CNO,
                    name = info.Name,
                    is_buy_active = info.BuyOption?.Enable ?? false,
                    is_sell_active = info.SellOption?.Enable ?? false,
                    grid_count = info.BuyOption?.GridCount ?? info.SellOption?.GridCount ?? 5
                };
                db.SetOption(channelOpt);

                // 구매 프로파일들 동기화
                if (info.BuyOption != null)
                {
                    var buyProfiles = info.BuyOption.GetProfiles(info.CNO);
                    foreach (var profile in buyProfiles) db.SetGridProfile(profile);
                }

                // 판매 프로파일들 동기화
                if (info.SellOption != null)
                {
                    var sellProfiles = info.SellOption.GetProfiles(info.CNO);
                    foreach (var profile in sellProfiles) db.SetGridProfile(profile);
                }
            }
        }

        /// <summary>
        /// 클래스이름으로 전체 타입 경로를 찾아줍니다. (GG.GlobalGold, GMK.GMK 등)
        /// </summary>
        private static string FindFullTypeName(string className)
        {
            // 하드코딩 방식 대신, 리플렉션이나 다른 동적 탐색 방법 고려 가능
            if (className == "GlobalGold") return "XTA.Channels.GG.GlobalGold";
            if (className == "LFT") return "XTA.Channels.GG.LFT";
            if (className == "GMK") return "XTA.Channels.GMK.GMK";
            if (className == "MM") return "XTA.Channels.GMK.MM";
            if (className == "XHANA") return "XTA.Channels.XSim.XHANA";
            if (className == "XDUNA") return "XTA.Channels.XSim.XDUNA";

            return $"XTA.Channels.{className}";
        }

        private static void EnsureConfigFile(string configPath)
        {
            if (File.Exists(configPath)) return;

            nlog.Warn($"[Startup] Config file not found. Creating default config: {configPath}");

            try
            {
                string? dir = Path.GetDirectoryName(configPath);
                if (!string.IsNullOrEmpty(dir) && !Directory.Exists(dir))
                {
                    Directory.CreateDirectory(dir);
                }

                var channels = new Dictionary<string, XChannelInfo>();

                // Helper with ClassName metadata
                XChannelInfo CreateTradeChannel(long id, int cno, string name, string className)
                {
                    var gridSettings = new List<string> {
                        "0,1,1,0.1,500,200,50,400,100,500,0"
                    };

                    return new XChannelInfo(id, cno, name, "TRADE")
                    {
                        RunMode = "Live",
                        IsSoundEnabled = true,
                        CNO = cno,
                        CID = id,
                        Plugin = new XPluginConfig { ClassName = className },
                        BuyOption = new BuyOption
                        {
                            Enable = true,
                            GridCount = 1,
                            Profiles = new List<string>(gridSettings)
                        },
                        SellOption = new SellOption
                        {
                            Enable = true,
                            GridCount = 1,
                            Profiles = new List<string>(gridSettings)
                        }
                    };
                }

                channels["-1002204600811"] = CreateTradeChannel(-1002204600811, 1001, "GLOBAL GOLD", "GlobalGold");
                channels["-1001658145217"] = CreateTradeChannel(-1001658145217, 1002, "GMK", "GMK");
                channels["-1000000002001"] = CreateTradeChannel(-1000000002001, 2001, "LFT", "GMK");
                channels["-1000000002002"] = CreateTradeChannel(-1000000002002, 2002, "MM", "GMK");
                channels["-1003778889507"] = CreateTradeChannel(-1003778889507, 3001, "HANA", "GlobalGold");
                channels["-1003697953708"] = CreateTradeChannel(-1003697953708, 3002, "DUNA", "GMK");
                string appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
                string commonPath = Path.Combine(appData, @"MetaQuotes\Terminal\Common\Files");

                var defaultConfig = new XConfig
                {
                    Version = "1.0.0",
                    SystemSettings = new XSystemSettings
                    {
                        Paths = new XPathSettings
                        {
                            ProdDbFullpath = Path.Combine(commonPath, "XTA.db"),
                            TestDbFullpath = Path.Combine(commonPath, "XTA_TEST.db"),
                            LogRootDir = "_log"
                        },
                        Logging = new XLoggingSettings
                        {
                            GlobalLogLevel = "Trace",
                            EnableAllChannelLogs = true
                        },
                        Window = new XWindowSettings
                        {
                            Left = 100,
                            Top = 100,
                            Width = 1650,
                            Height = 900
                        }
                    },
                    Channels = channels
                };

                try
                {
                    var options = new JsonSerializerOptions { WriteIndented = true };
                    string defaultJson = JsonSerializer.Serialize(defaultConfig, options);
                    File.WriteAllText(configPath, defaultJson);
                    nlog.Info("[Startup] Default config file created with new Buy/Sell settings structure.");
                }
                catch (Exception ex)
                {
                    nlog.Error(ex, "[Startup] Failed to create default config file.");
                }
            }
            catch (Exception ex)
            {
                nlog.Error(ex, $"[Startup] Directory creation or config preparation failed for: {configPath}");
            }
        }
    }
}

