using System.Configuration;
using System.Data;
using System.IO;
using System.Windows;
using XTA;
using XTA.Models;

namespace ATSA
{
    /// <summary>
    /// Interaction logic for App.xaml
    /// </summary>
    public partial class App : Application
    {
        public static XParameter Param { get; private set; } = null!;

        protected override void OnStartup(StartupEventArgs e)
        {
            base.OnStartup(e);

            // 1. 설정 경로 결정 (_config 폴더)
            string configPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "_config", "ASTA.json");

            try
            {
                // 2. Core Engine 초기화 (XTAStartup 활용)
                Param = XTAStartup.Initialize(configPath);

                // 2-1. UI Project Shared Param Initialization
                //XTA.App.UI.XTAViewModelBase.XParam = Param;

                // [v4.5] 사운드 서비스를 XTA.Infrastructure.Audio 프로젝트에서 초기화
                var soundService = new XTA.Infrastructure.Audio.XSoundService(Param);
                Param.Add(soundService);

                // [v4.7] TTS 서비스 초기화 및 등록
                var ttsService = new XTA.Infrastructure.Audio.XTtsService(Param);
                Param.Add(ttsService);

                // [v1.1] 모든 서비스(코어+확장) 일괄 시작
                XTAStartup.Start(Param);

                // [v1.2] 설정 재로드(Hot-Reload) 메시지 핸들러 등록
                Param.messenger.Register<XDataObject>(this, "CONFIG_RELOAD_REQ", true, xdo =>
                {
                    if (!string.IsNullOrEmpty(xdo.Text))
                    {
                        XTAStartup.ReloadConfig(Param, xdo.Text);
                    }
                });

                Param.nlog.Info("XTA Engine initialized and started successfully.");
            }
            catch (Exception ex)
            {
                MessageBox.Show($"XTA Engine 초기화 오류:\n{ex}", "Fatal Error", MessageBoxButton.OK, MessageBoxImage.Error);
                Shutdown();
                return;
            }

            // 3. 메인 윈도우 표시 (MainWindow 생성자에서 ASTA.json 설정 자동 적용)
            var mainWindow = new MainWindow();
            mainWindow.Show();
        }
    }
}

