using DevExpress.Data.Filtering;
using DevExpress.Mvvm;
using DevExpress.Xpo;
using DevExpress.Xpo.DB;
using NLog;
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using XTA.XData.Models;
using XTA.XData.Interfaces;
using XTA.XData.Services;
using XTA.Models;
using XTA.Extensions;

namespace XTA.Infrastructure.Data
{
    /// <summary>
    /// XPO 기반 SQLite 데이터 서비스 (XObject 상속 복구 및 XpoHelper 활용)
    /// </summary>
    public class XpoSqliteService : XObject, ISignalRepository, IChannelOptionRepository, IGridProfileRepository
    {
        private IDataLayer? _dataLayer;
        private readonly string _dbPath;
        private readonly object _initLock = new object();

        private readonly ConcurrentQueue<XDataObject> _signalQueue = new();
        private readonly ConcurrentQueue<XDataObject> _messageQueue = new();
        private System.Threading.CancellationTokenSource? _dbLoopCancelSource;

        public XpoSqliteService(XParameter param) : base(param)
        {
            _dbPath = param.Config?.SystemSettings?.Paths?.ProdDbFullpath ?? "XTA.db";
        }

        public void Initialize()
        {
            if (_dataLayer != null) return;
            lock (_initLock)
            {
                if (_dataLayer != null) return;
                try
                {
                    string? dbDir = System.IO.Path.GetDirectoryName(_dbPath);
                    if (!string.IsNullOrEmpty(dbDir) && !System.IO.Directory.Exists(dbDir)) System.IO.Directory.CreateDirectory(dbDir);

                    string connStr = SQLiteConnectionProvider.GetConnectionString(_dbPath);
                    var dict = new DevExpress.Xpo.Metadata.ReflectionDictionary();
                    dict.CollectClassInfos(typeof(XpoSignal).Assembly);

                    var store = XpoDefault.GetConnectionProvider(connStr, AutoCreateOption.DatabaseAndSchema);
                    if (store is SQLiteConnectionProvider sqliteProvider)
                    {
                        try { using var cmd = sqliteProvider.Connection.CreateCommand(); cmd.CommandText = "PRAGMA journal_mode=WAL; PRAGMA synchronous=NORMAL;"; cmd.ExecuteNonQuery(); }
                        catch { }
                    }

                    _dataLayer = new ThreadSafeDataLayer(dict, store);
                    _dataLayer.UpdateSchema(false, dict.CollectClassInfos(typeof(XpoSignal).Assembly).ToArray());
                }
                catch (Exception ex) { nlog.Fatal(ex, $"[XData] XPO INIT FAILED! Path: {_dbPath}"); throw; }
            }
        }

        public IDataLayer GetLayer() { if (_dataLayer == null) Initialize(); return _dataLayer!; }

        private bool _isStarted = false;
        public override void Start()
        {
            lock (_initLock)
            {
                if (_isStarted) return;
                _isStarted = true;
            }

            Initialize();
            messenger.Register<XDataObject>(this, "DB_SAVE_SIGNAL", true, xdo => _signalQueue.Enqueue(xdo));
            messenger.Register<XDataObject>(this, "DB_SAVE_MSG", true, xdo => _messageQueue.Enqueue(xdo));
            messenger.Register<XDataObject>(this, "DB_MANUAL_TRANSFER", true, xdo => Task.Run(() => ArchiveSignalsInternal()));

            _dbLoopCancelSource = new System.Threading.CancellationTokenSource();
            Task.Run(ProcessSignalQueue, _dbLoopCancelSource.Token);
            Task.Run(ProcessMessageQueue, _dbLoopCancelSource.Token);
            Task.Run(ProcessArchivingQueue, _dbLoopCancelSource.Token);
            nlog.Trace("XpoSqliteService Started.");
        }

        public override void Stop() { _dbLoopCancelSource?.Cancel(); messenger.Unregister(this); _dataLayer?.Dispose(); }

        #region ISignalRepository Implementation
        public async Task<XTA.XData.Models.XSignal?> GetSignalBySidAsync(string sid)
        {
            var xpo = await GetLayer().FindObjectAsync<XpoSignal>(CriteriaOperator.Parse("sid = ?", sid));
            return xpo?.ToDomainModel();
        }

        public async Task<List<XTA.XData.Models.XSignal>> GetSignalsByCnoAsync(int cno, int count = 500)
        {
            string tagPattern = $"%({cno})%";
            var criteria = cno > 0 ? CriteriaOperator.Parse("cno = ? OR tag LIKE ?", cno, tagPattern) : CriteriaOperator.Parse("True");
            var sorts = new[] { new SortProperty("sid", SortingDirection.Ascending) };
            var list = await GetLayer().FindListAsync<XpoSignal>(criteria, sorts);
            if (count > 0) return list.Take(count).Select(x => x.ToDomainModel()).ToList();
            return list.Select(x => x.ToDomainModel()).ToList();
        }

        public List<XTA.XData.Models.XSignal> GetSignalsByCno(int cno, int count = 500) => GetSignalsByCnoAsync(cno, count).Result;

        public async Task SaveSignalAsync(XTA.XData.Models.XSignal signal) => messenger.SendDbSaveSignal(signal as XTA.Models.XSignal ?? XTA.Models.XSignal.FromBase(signal));

        public async Task UpdateSignalStatusAsync(string sid, int xeStatus, string xeStatusMsg)
        {
            using var uow = new UnitOfWork(GetLayer());
            var xpo = await uow.FindObjectAsync<XpoSignal>(CriteriaOperator.Parse("sid = ?", sid));
            if (xpo != null)
            {
                xpo.SetXeStatus(xeStatus); xpo.xe_status_msg = xeStatusMsg; xpo.updated = DateTime.Now;
                var h = new XpoSignalStatusHistory(uow) { ref_id = xpo.id, sid = xpo.sid, xe_status = xeStatus, time = DateTime.Now, msg = xeStatusMsg ?? string.Empty };
                await uow.CommitChangesAsync();

                // [Fix] ToDomainModel()은 XTA.XData.Models.XSignal을 반환하므로, 
                // UI용 모델인 XTA.Models.XSignal로 변환하기 위해 FromBase를 사용
                var domainSignal = xpo.ToDomainModel();
                messenger.Send(new XDataObject { Signal = XTA.Models.XSignal.FromBase(domainSignal) }, "DB_SIGNAL_UPDATED");
            }
        }

        public async Task UpdateXaStatusAsync(string sid, int xaStatus)
        {
            using var uow = new UnitOfWork(GetLayer());
            var xpo = await uow.FindObjectAsync<XpoSignal>(CriteriaOperator.Parse("sid = ?", sid));
            if (xpo != null)
            {
                xpo.xa_entry = xaStatus;
                xpo.updated = DateTime.Now;
                await uow.CommitChangesAsync();
                nlog.Info($"[DB:XA-AUTH] SID:{sid} updated to XA_ENTRY:{xaStatus} (Auto-Authorized)");
            }
        }

        public async Task<int> SaveRawSignalAsync(XTA.XData.Models.XSignal signal, string rawText)
        {
            using var uow = new UnitOfWork(GetLayer());
            var raw = new XpoSignalRaw(uow) { symbol = signal.symbol, dir = signal.dir, type = signal.type, price = signal.price_signal, lot = signal.lot, sno = signal.sno, raw_text = rawText ?? string.Empty, created_at = DateTime.Now };
            await uow.CommitChangesAsync(); return raw.Oid;
        }

        public async Task DeleteSignalAsync(string sid)
        {
            using var uow = new UnitOfWork(GetLayer());
            var xpo = await uow.FindObjectAsync<XpoSignal>(CriteriaOperator.Parse("sid = ?", sid));
            if (xpo != null) { xpo.Delete(); await uow.CommitChangesAsync(); }
        }

        public async Task<XTA.XData.Models.XSignal?> FindLastActiveSignalBySnoAsync(int cno, int sno)
        {
            var criteria = CriteriaOperator.Parse("(cno = ? OR tag LIKE ?) AND sno = ? AND ((xa_entry > ? AND xe_status < ?) OR (xa_exit > ?))", 
                cno, $"%({cno})%", sno, XCode.XA_RAW, (int)XCode.EaStatus.Closed_Signal, XCode.XA_RAW);
            var list = await GetLayer().FindListAsync<XpoSignal>(criteria, new SortProperty("created", SortingDirection.Descending));
            return list.FirstOrDefault()?.ToDomainModel();
        }

        public async Task<List<XTA.XData.Models.XSignal>> FindActiveSignalsBySnoAsync(int cno, int sno)
        {
            var criteria = CriteriaOperator.Parse("(cno = ? OR tag LIKE ?) AND sno = ? AND ((xa_entry > ? AND xe_status < ?) OR (xa_exit > ?))", 
                cno, $"%({cno})%", sno, XCode.XA_RAW, (int)XCode.EaStatus.Closed_Signal, XCode.XA_RAW);
            var list = await GetLayer().FindListAsync<XpoSignal>(criteria, new SortProperty("created", SortingDirection.Descending));
            return list.Select(x => x.ToDomainModel()).ToList();
        }

        public async Task<List<XTA.XData.Models.XSignal>> GetAllActiveSignalsAsync()
        {
            var criteria = CriteriaOperator.Parse("(xa_entry > ? AND xe_status < ?) OR (xa_exit > ?)", XCode.XA_RAW, (int)XCode.EaStatus.Closed_Signal, XCode.XA_RAW);
            var list = await GetLayer().FindListAsync<XpoSignal>(criteria);
            return list.Select(x => x.ToDomainModel()).ToList();
        }
        #endregion

        #region IChannelOptionRepository Implementation
        public async Task<XTA.XData.Models.XChannelOption?> GetOptionAsync(int cno)
        {
            var xpo = await GetLayer().FindObjectAsync<XpoChannelOption>(CriteriaOperator.Parse("cno = ?", cno));
            return xpo?.ToDomainModel();
        }

        public async Task SaveOptionAsync(XTA.XData.Models.XChannelOption option) => await GetLayer().SaveObjectAsync<XpoChannelOption>((xpo, uow) => option.ToXpoModel(xpo), CriteriaOperator.Parse("cno = ?", option.cno));
        public async Task<List<XTA.XData.Models.XChannelOption>> GetAllOptionsAsync() => (await GetLayer().FindListAsync<XpoChannelOption>(CriteriaOperator.Parse("True"))).Select(x => x.ToDomainModel()).ToList();
        public void SetOption(XTA.XData.Models.XChannelOption option) => _ = SaveOptionAsync(option);
        public XTA.XData.Models.XChannelOption? GetOption(int cno) => GetOptionAsync(cno).Result;
        #endregion

        #region IGridProfileRepository Implementation
        public async Task<XTA.XData.Models.XGridProfile?> GetGridProfileAsync(int cno, int dir, int gno)
        {
            var xpo = await GetLayer().FindObjectAsync<XpoGridProfile>(CriteriaOperator.Parse("cno = ? AND dir = ? AND gno = ?", cno, dir, gno));
            return xpo?.ToDomainModel();
        }

        public async Task<List<XTA.XData.Models.XGridProfile>> GetGridProfilesAsync(int cno, int dir) => (await GetLayer().FindListAsync<XpoGridProfile>(CriteriaOperator.Parse("cno = ? AND dir = ?", cno, dir), new SortProperty("gno", SortingDirection.Ascending))).Select(x => x.ToDomainModel()).ToList();
        public async Task SaveGridProfileAsync(XTA.XData.Models.XGridProfile profile) => await GetLayer().SaveObjectAsync<XpoGridProfile>((xpo, uow) => profile.ToXpoModel(xpo), CriteriaOperator.Parse("cno = ? AND dir = ? AND gno = ?", profile.cno, profile.dir, profile.gno));
        public List<XTA.XData.Models.XGridProfile> GetGridProfiles(int cno, int dir) => GetGridProfilesAsync(cno, dir).Result;
        public void SetGridProfile(XTA.XData.Models.XGridProfile profile) => _ = SaveGridProfileAsync(profile);
        #endregion

        public async Task ClearAllSignalsAsync()
        {
            using var uow = new UnitOfWork(GetLayer());
            try
            {
                // [안전 가드] EA가 관리를 포기하지 않도록, 이미 청산된(xe_status >= 20) 신호만 삭제합니다.
                await uow.ExecuteNonQueryAsync($"DELETE FROM signals WHERE xe_status >= {(int)XCode.EaStatus.Closed_Signal}");

                // 삭제되지 않은 활성 신호(xe_status < 20)의 이력은 남기고, 나머지만 삭제합니다.
                await uow.ExecuteNonQueryAsync($"DELETE FROM signal_status_history WHERE sid NOT IN (SELECT sid FROM signals)");
                await uow.ExecuteNonQueryAsync("DELETE FROM signals_history");

                await uow.CommitChangesAsync();
                nlog.Info($"[DB] Completed signals (xe_status >= {(int)XCode.EaStatus.Closed_Signal}) and history have been cleared.");
            }
            catch (Exception ex)
            {
                nlog.Error(ex, "[DB] Failed to clear signals.");
                throw;
            }
        }

        private async Task ProcessSignalQueue()
        {
            while (_dbLoopCancelSource != null && !_dbLoopCancelSource.IsCancellationRequested)
            {
                try
                {
                    if (!_signalQueue.IsEmpty)
                    {
                        using var uow = new UnitOfWork(GetLayer());
                        var newHistories = new List<XpoSignalStatusHistory>();
                        var batchCache = new Dictionary<string, XpoSignal>();
                        int batchCount = 0;

                        while (_signalQueue.TryDequeue(out var xdo))
                        {
                            if (xdo?.Signal == null) continue;
                            var signal = xdo.Signal;
                            string sid = signal.sid ?? string.Empty;
                            if (string.IsNullOrEmpty(sid)) continue;

                            // [v8.8] DB 저장 전 최종 규격 검증 (가드)
                            if (!XIdManager.Instance.IsValidSid(sid))
                            {
                                nlog.Warn($"[DB:GUARD] Invalid SID format detected. Skipping save: {sid}");
                                continue;
                            }

                            // 1. 배치 캐시 또는 DB에서 기존 객체 검색
                            if (!batchCache.TryGetValue(sid, out var existing))
                            {
                                existing = await uow.FindObjectAsync<XpoSignal>(CriteriaOperator.Parse("sid = ?", sid));
                                if (existing != null) batchCache[sid] = existing;
                            }

                            bool isNew = existing == null;

                            if (isNew)
                            {
                                existing = new XpoSignal(uow) { created = DateTime.Now, sid = sid };
                                batchCache[sid] = existing;
                            }

                            int oldStatus = isNew ? -1 : existing!.xe_status;

                            // 2. 데이터 업데이트
                            var target = existing!; 
                            signal.ToXpoModel(target);
                            target.updated = DateTime.Now;

                            // [Fix] 신규 생성 또는 상태(xe_status) 변경 시 히스토리 기록
                            if (isNew || oldStatus != target.xe_status)
                            {
                                string msg = isNew ? "Initial Signal Received" : (xdo.CMD ?? "Status Updated via App");
                                newHistories.Add(new XpoSignalStatusHistory(uow) { sid = target.sid, xe_status = target.xe_status, time = DateTime.Now, msg = msg });
                            }
                            batchCount++;
                        }

                        if (batchCount > 0)
                        {
                            await uow.CommitChangesAsync();
                            // History의 ref_id 채우기
                            foreach (var h in newHistories)
                            {
                                var s = await uow.FindObjectAsync<XpoSignal>(CriteriaOperator.Parse("sid = ?", h.sid));
                                if (s != null) h.ref_id = s.id;
                            }
                            await uow.CommitChangesAsync();
                        }
                    }
                }
                catch (Exception ex) { nlog.Error(ex, "[DB] Signal Queue Error"); }
                await Task.Delay(500);
            }
        }

        private async Task ProcessMessageQueue()
        {
            while (_dbLoopCancelSource != null && !_dbLoopCancelSource.IsCancellationRequested)
            {
                try { if (!_messageQueue.IsEmpty) { using var uow = new UnitOfWork(GetLayer()); int batchCount = 0; while (_messageQueue.TryDequeue(out var xdo)) { var msg = new XpoTgMessage(uow) { CID = xdo.CID, Time = xdo.Timestamp == DateTime.MinValue ? DateTime.Now : xdo.Timestamp, CNO = xdo.CNO, Text = xdo.Text ?? string.Empty, Status = 0 }; batchCount++; } if (batchCount > 0) await uow.CommitChangesAsync(); } }
                catch (Exception ex) { nlog.Error(ex, "[DB] Message Queue Error"); }
                await Task.Delay(1000);
            }
        }

        private async Task ProcessArchivingQueue() { while (_dbLoopCancelSource != null && !_dbLoopCancelSource.IsCancellationRequested) { try { await ArchiveSignalsInternal(); } catch (Exception ex) { nlog.Error(ex, "[DB] Archiving Loop Error"); } await Task.Delay(TimeSpan.FromSeconds(3)); } }

        private async Task ArchiveSignalsInternal()
        {
            try
            {
                int archiveCount = 0;
                using var uow = new UnitOfWork(GetLayer());

                // [v8.7] 청산된 신호의 가독성을 위해 2초 지연 이관(삭제) 로직 적용 (20s -> 2s)
                var delayThreshold = DateTime.Now.AddSeconds(-2);
                var closedSignals = new XPCollection<XpoSignal>(uow, 
                    CriteriaOperator.Parse("xe_status >= ? AND updated < ?", 
                    (int)XCode.EaStatus.Closed_Signal, delayThreshold)).ToList();

                foreach (var s in closedSignals) 
                { 
                    var history = new XpoSignalHistory(uow);
                    s.ToHistoryModel(history);
                    s.Delete(); 
                    archiveCount++; 
                }
                if (archiveCount > 0) { await uow.CommitChangesAsync(); nlog.Info($"[DB] Archived {archiveCount} signals to history after 20s delay (Handshake Done)."); }
            }
            catch (Exception ex) { nlog.Error(ex, "[DB] Archiving Process Error"); }
        }
    }
