using NLog;
using System;
using System.Collections.Concurrent;
using System.Collections.Generic;
using System.Linq;
using XTA.Infrastructure.Data;
using XTA.XData.Interfaces;
using XTA.XData.Models;
using static XTA.XData.Models.XCode;
using XTA.Models;
using XTA.Interfaces;
using XTA.Core;
using FluentSeq;
using System.Threading.Tasks;
using System.Threading.Channels;
using System.Threading;

namespace XTA.Services
{
    /// <summary>
    /// 텔레그램 메시지와 인터프리터 사이의 관문 역할을 하는 서비스.
    /// [Thread-Safe] 생산자-소비자 패턴(Channel)을 도입하여 동시성 문제를 해결함.
    /// </summary>
    public class XGatewayService : XChannelObject, IXGatewayService
    {
        public ConcurrentDictionary<string, XDataObject> PendingSignals { get; } = new();

        public event Action<XDataObject>? SignalAddedOrUpdated;
        public event Action<string>? SignalRemoved;

        private ISequence<HubState> _sequence = null!;
        private readonly Channel<XDataObject> _msgChannel = Channel.CreateUnbounded<XDataObject>();
        private CancellationTokenSource? _cts;

        // 현재 처리 중인 메시지 컨텍스트 (소비자 루프에서만 접근)
        private XDataObject? _currentXdo;
        private XChannelInfo? _currentInfo;

        public XGatewayService(XParameter param) : base(param, new XChannelInfo(0, 0, "GATEWAY_HUB", "SYSTEM"))
        {
            InitSequence();
        }

        private void InitSequence()
        {
            _sequence = new FluentSeq<HubState>()
                .Create(HubState.Received)
                .ActivateDebugLogging(nlog)

                // 1. 초기 상태: 수신됨
                .ConfigureState(HubState.Received)
                    .OnEntry(() => {
                        if (_currentXdo == null) return;
                        nlog.Trace($"[SIGNAL:STEP-1:RAW] New message {{ MsgId={_currentXdo.MsgId}, CID={_currentXdo.CID}, TextLen={_currentXdo.Text?.Length ?? 0} }}");
                        if (_currentInfo != null)
                        {
                            _currentXdo.CNO = _currentInfo.CNO;
                            // DB 저장은 별도 태스크로 수행
                            _ = XContext.Instance.Data?.SaveMessageAsync(_currentXdo);
                            this.Log($"[TG] {_currentInfo.Name} 채널로부터 메시지 수신 (MsgId:{_currentXdo.MsgId})");
                        }
                    })

                // 2. 해석 완료 상태 (성공)
                .ConfigureState(HubState.Interpreted)
                    .TriggeredBy(() => _currentInfo != null && _currentInfo.Type.ToUpper() == "TRADE" && _currentInfo.CNO != 2001 && _currentInfo.CNO != 2002)
                        .WhenInState(HubState.Received)
                    .OnEntry(() => {
                        nlog.Trace($"[SIGNAL:STEP-1:ROUTE] Routing to interpreter {{ CNO={_currentInfo!.CNO}, Name=\"{_currentInfo.Name}\", MsgId={_currentXdo?.MsgId} }}");

                        // CNO에 해당하는 인터프리터를 찾아 직접 호출
                        var interpreter = param.GetService<XInterpreterBase>(i => i.Info.CNO == _currentInfo.CNO);
                        if (interpreter != null)
                        {
                            interpreter.EnqueueMessage(_currentXdo!);
                        }
                        else
                        {
                            nlog.Warn($"[SIGNAL:STEP-1:FAIL] Interpreter not found for CNO:{_currentInfo.CNO}");
                        }
                    })

                // 3. 실패 또는 제외 상태
                .ConfigureState(HubState.Failed)
                    .TriggeredBy(() => _currentInfo == null)
                        .WhenInState(HubState.Received)
                    .TriggeredBy(() => _currentInfo != null && (_currentInfo.Type.ToUpper() != "TRADE" || _currentInfo.CNO == 2001 || _currentInfo.CNO == 2002))
                        .WhenInState(HubState.Received)
                    .OnEntry(() => {
                        if (_currentInfo == null) {
                            nlog.Trace($"[SIGNAL:STEP-1:DROP] Unknown channel {{ CID={_currentXdo?.CID}, MsgId={_currentXdo?.MsgId} }}");
                        } else {
                            nlog.Trace($"[SIGNAL:STEP-1:SKIP] Non-TRADE or UI channel {{ CNO={_currentInfo!.CNO}, Type=\"{_currentInfo.Type}\", MsgId={_currentXdo?.MsgId} }}");
                        }
                    })

                .Builder()
                .DisableValidation()
                .Build();
        }

        public void EnqueueRawMessage(XDataObject xdo) => OnRawMessageReceived(xdo);

        public void Log(string message)
        {
            nlog.Info($"[LOG:HUB] {message}");
            // 필요 시 UI나 시스템 로그로 전파하는 이벤트 추가 가능
        }

        private bool _isStarted = false;
        private readonly HashSet<int> _processedMsgIds = new();

        public override void Start()
        {
            lock (_processedMsgIds)
            {
                if (_isStarted) return;
                _isStarted = true;
            }

            _cts = new CancellationTokenSource();

            // 소비자 루프 시작 (백그라운드 태스크)
            Task.Run(() => ProcessMessageQueueAsync(_cts.Token));
        }

        public override void Stop()
        {
            _cts?.Cancel();
            _isStarted = false;
        }

        /// <summary>
        /// 메시지를 큐에 적재 (생산자)
        /// </summary>
        private void OnRawMessageReceived(XDataObject xdo)
        {
            if (xdo == null) return;

            // [Algorithm: Idempotency] 동일 MsgId 중복 처리 방지 (최초 진입점 차단)
            lock (_processedMsgIds)
            {
                if (_processedMsgIds.Contains(xdo.MsgId))
                {
                    nlog.Trace($"[Gateway:SKIP] Message already processed: MsgId={xdo.MsgId}");
                    return;
                }
                _processedMsgIds.Add(xdo.MsgId);

                if (_processedMsgIds.Count > 1000) _processedMsgIds.Remove(_processedMsgIds.First());
            }

            // 채널 큐에 메시지 쓰기
            if (!_msgChannel.Writer.TryWrite(xdo))
            {
                nlog.Error($"[Gateway:ERROR] Failed to write message to channel queue: MsgId={xdo.MsgId}");
            }
        }

        /// <summary>
        /// 큐에서 메시지를 꺼내어 순차적으로 처리 (소비자)
        /// 이 메서드 내에서만 _sequence와 _currentXdo를 사용하므로 스레드 안전함.
        /// </summary>
        private async Task ProcessMessageQueueAsync(CancellationToken ct)
        {
            nlog.Info("[Gateway:CONSUMER] Background message consumer started.");

            try
            {
                while (await _msgChannel.Reader.WaitToReadAsync(ct))
                {
                    while (_msgChannel.Reader.TryRead(out var xdo))
                    {
                        try
                        {
                            _currentXdo = xdo;
                            _currentInfo = param.GetChannel(xdo.CID);

                            _sequence.SetState(HubState.Received);

                            int safetyCounter = 0;
                            while (_sequence.IsInState(HubState.Received) && safetyCounter++ < 2)
                            {
                                _sequence.Run();
                            }
                        }
                        catch (Exception ex)
                        {
                            nlog.Error(ex, $"[Gateway:CONSUMER] Error processing message: MsgId={xdo?.MsgId}");
                        }
                        finally
                        {
                            _currentXdo = null;
                            _currentInfo = null;
                        }
                    }
                }
            }
            catch (OperationCanceledException)
            {
                nlog.Info("[Gateway:CONSUMER] Background consumer cancelled.");
            }
            catch (Exception ex)
            {
                nlog.Fatal(ex, "[Gateway:CONSUMER] Critical error in message consumer loop.");
            }
        }

        public async Task ProcessInterpretedSignalAsync(XDataObject xdo)
        {
            await OnSignalInterpretedAsync(xdo);
        }

        private async Task OnSignalInterpretedAsync(XDataObject xdo)
        {
            try
            {
                if (xdo?.Signal == null) return;

                var sMaster = xdo.Signal;

                var validator = new XTA.Validation.XSignalValidator();
                var valResult = validator.Validate(sMaster);
                if (!valResult.IsValid)
                {
                    string errorMsg = string.Join(", ", valResult.Errors.Select(e => e.ErrorMessage));
                    nlog.Warn($"[SIGNAL:INVALID] {errorMsg} (Text: {xdo.Text})");
                    return;
                }

                nlog.Info($"[SIGNAL:STEP-3:HUB] Interpreter result {{ SID=\"{sMaster.sid}\", CNO={sMaster.cno}, SNO={sMaster.sno}, MsgId={xdo.MsgId} }}");

                if (sMaster.cmd != XCode.CLOSE)
                {
                    XContext.Instance.Sound?.PlaySound(sMaster, "SIGNAL_RECEIVED");
                }

                var dbService = param.GetService<ISignalRepository>();
                if (dbService != null)
                {
                    int rawId = await dbService.SaveRawSignalAsync(sMaster, xdo.Text ?? string.Empty);
                    sMaster.raw_id = rawId;
                }

                var processedSignals = await ApplyChannelOptionsAsync(xdo);
                if (processedSignals == null || processedSignals.Count == 0) return;

                var uniqueSignals = processedSignals.GroupBy(s => s.sid).Select(g => g.First()).ToList();

                foreach (var s in uniqueSignals)
                {
                    nlog.Info($"[Gateway:PROCESS] >>> Processing individual signal branch: SNO:{s.sno} | Cmd:{s.cmd} (Total Branches: {uniqueSignals.Count})");

                    if (s.cmd == XCode.CLOSE)
                    {
                        nlog.Info($"[Gateway:CLOSE-PATH] Routing SNO:{s.sno} to CloseProcessor.");
                        await ProcessCloseCommandAsync(s, xdo.MsgId);
                        continue;
                    }

                    s.updated = DateTime.Now;
                    s.SetXeStatus((int)XCode.EaStatus.Ready);
                    s.Validate();
                    var signalXdo = new XDataObject
                    {
                        Signal = s,
                        MsgId = xdo.MsgId,
                        Text = xdo.Text,
                        CID = xdo.CID,
                        CNO = xdo.CNO
                    };

                    PendingSignals.AddOrUpdate(s.sid, signalXdo, (key, existingVal) => signalXdo);

                    if (XContext.Instance.Data != null)
                    {
                        await XContext.Instance.Data.SaveSignalAsync(s);
                        nlog.Info($"[Gateway:ENTRY] Successfully inserted/updated signal to DB. SID:{s.sid} | CNO:{s.cno} | SNO:{s.sno} | Dir:{s.dir} | Lot:{s.lot} | Price:{s.price_signal}");
                    }

                    SignalAddedOrUpdated?.Invoke(signalXdo);
                    nlog.Info($"[Gateway:PROCESS] <<< Completed individual signal branch: SNO:{s.sno}");
                }
            }
            catch (Exception ex)
            {
                nlog.Error(ex, "[Gateway] Critical error in OnSignalInterpreted.");
            }
        }

        private async Task ProcessCloseCommandAsync(XTA.Models.XSignal signal, int msgId)
        {
            var dbService = param.GetService<XpoSqliteService>();
            var repo = param.GetService<ISignalRepository>();

            nlog.Info($"[Gateway:CLOSE] >>> Starting Close Process for CNO:{signal.cno} SNO:{signal.sno} (MsgId:{msgId})");

            var targets = new List<XTA.XData.Models.XSignal>();

            var pendingMatches = PendingSignals.Values
                .Where(x => x.Signal != null && x.Signal.cno == signal.cno && x.Signal.sno == signal.sno)
                .Select(x => (XTA.XData.Models.XSignal)x.Signal!)
                .ToList();

            if (pendingMatches.Any())
            {
                targets.AddRange(pendingMatches);
                nlog.Info($"[Gateway:CLOSE] Matched {pendingMatches.Count} signals from Memory Cache.");
            }

            if (dbService != null)
            {
                var dbMatches = await dbService.FindActiveSignalsBySnoAsync(signal.cno, signal.sno);
                int dbCount = 0;
                foreach (var dbm in dbMatches)
                {
                    if (!targets.Any(t => t.sid == dbm.sid)) 
                    {
                        targets.Add(dbm);
                        dbCount++;
                    }
                }
                if (dbCount > 0) nlog.Info($"[Gateway:CLOSE] Matched {dbCount} additional signals from Database.");
            }

            if (targets.Count > 0)
            {
                foreach (var targetEntry in targets)
                {
                    var finalSignal = targetEntry as XTA.Models.XSignal ?? XTA.Models.XSignal.FromBase(targetEntry);

                    if (PendingSignals.TryRemove(finalSignal.sid, out _))
                    {
                        SignalRemoved?.Invoke(finalSignal.sid);
                    }

                    finalSignal.msg_id = msgId;
                    finalSignal.cmd = XCode.CLOSE;
                    finalSignal.xa_exit = (int)XCode.XA_ACTIVE;
                    finalSignal.updated = DateTime.Now;

                    if (XContext.Instance.Data != null) await XContext.Instance.Data.SaveSignalAsync(finalSignal);

                    var signalXdo = new XDataObject { Signal = finalSignal, MsgId = msgId, CMD = "CLOSE_SIGNAL" };
                    SignalAddedOrUpdated?.Invoke(signalXdo);
                }

                this.Log($"[{signal.cno}] {signal.sno}회차 청산 처리 완료 ({targets.Count}건)");
                string soundCmd = (signal.sno == 0) ? "GROUP_CLOSE" : "SID_CLOSE";
                XContext.Instance.Sound?.PlaySound(signal, soundCmd);
            }
            else
            {
                var lastActive = await dbService!.FindLastActiveSignalBySnoAsync(signal.cno, signal.sno);
                int validDir = lastActive?.dir ?? (signal.dir > 0 ? signal.dir : 1);

                var finalSignal = signal;
                finalSignal.dir = validDir;
                finalSignal.type = 9;
                finalSignal.sid = XIdManager.Instance.GenerateSid(finalSignal.cno, DateTime.Now, finalSignal.sno, 0, finalSignal.dir, 9);
                finalSignal.gid = XIdManager.Instance.GenerateGid(finalSignal.cno, DateTime.Now, finalSignal.sno);
                finalSignal.symbol = "GOLD";
                finalSignal.lot = 0.0;

                finalSignal.msg_id = msgId;
                finalSignal.cmd = XCode.CLOSE;
                finalSignal.type = 9;
                finalSignal.xa_exit = (int)XCode.XA_ACTIVE;
                finalSignal.SetXeStatus((int)XCode.EaStatus.Closed_Signal); 
                finalSignal.updated = DateTime.Now;

                if (XContext.Instance.Data != null) await XContext.Instance.Data.SaveSignalAsync(finalSignal);

                var signalXdo = new XDataObject { Signal = finalSignal, MsgId = msgId, CMD = "CLOSE_SIGNAL" };
                SignalAddedOrUpdated?.Invoke(signalXdo);

                this.Log($"[{finalSignal.cno}] {finalSignal.sno}회차 활성 신호 없음 - 강제 청산 레코드 생성 (SID:{finalSignal.sid})");
                XContext.Instance.Sound?.PlaySound(finalSignal, "SID_CLOSE");
            }
        }

        private async Task<List<XTA.Models.XSignal>> ApplyChannelOptionsAsync(XDataObject xdo)
        {
            var result = new List<XTA.Models.XSignal>();
            var sMaster = xdo.Signal;
            if (sMaster == null) return result;

            try
            {
                var optRepo = param.GetService<IChannelOptionRepository>();
                var profileRepo = param.GetService<IGridProfileRepository>();
                var channelInfo = param.GetChannelByCno(sMaster.cno);

                var opt = optRepo != null ? await optRepo.GetOptionAsync(sMaster.cno) : null;

                if (opt != null)
                {
                    bool isActive = (sMaster.dir == 1) ? opt.is_buy_active : opt.is_sell_active;
                    if (!isActive) return result;
                }
                else if (channelInfo != null)
                {
                    bool isActive = (sMaster.dir == 1) 
                        ? (channelInfo.BuyOption?.Enable ?? false) 
                        : (channelInfo.SellOption?.Enable ?? false);
                    if (!isActive) return result;
                }

                if (sMaster.cmd == XCode.CLOSE)
                {
                    sMaster.Validate();
                    result.Add(sMaster);
                    return result;
                }

                var profilesFromConfig = new List<XGridProfile>();
                if (sMaster.dir == 1 && channelInfo?.BuyOption != null)
                {
                    profilesFromConfig = channelInfo.BuyOption.GetProfiles(sMaster.cno);
                }
                else if (sMaster.dir == -1 && channelInfo?.SellOption != null)
                {
                    profilesFromConfig = channelInfo.SellOption.GetProfiles(sMaster.cno);
                }

                var profilesFromDb = profileRepo != null ? await profileRepo.GetGridProfilesAsync(sMaster.cno, sMaster.dir) : new List<XGridProfile>();
                var targetProfiles = profilesFromConfig.Count > 0 ? profilesFromConfig : (profilesFromDb.Cast<XGridProfile>().ToList());

                if (targetProfiles.Count == 0)
                {
                    var s = sMaster.Clone();
                    s.gno = 0;
                    if (opt != null)
                    {
                        s.tp = (double)opt.tp_points;
                        s.sl = (double)opt.sl_points;
                        s.ts_step = opt.ts_step;
                        s.te_limit = opt.gap_min;
                        s.limit_offset = (s.dir == 1) ? opt.buy_entry_offset : opt.sell_entry_offset;
                        s.stop_offset = s.limit_offset;
                    }
                    s.symbol = s.symbol?.Replace("#", "") ?? string.Empty;
                    s.sid = string.Empty;
                    s.gid = string.Empty;
                    s.Validate();
                    result.Add(s);
                    return result;
                }

                double point = 0.01;
                foreach (var profile in targetProfiles)
                {
                    var s = sMaster.Clone();
                    s.gno = profile.gno;
                    s.type = profile.type;

                    if (profile.lot_type == 2) s.lot = Math.Round(sMaster.lot * profile.lot, 2);
                    else s.lot = profile.lot;

                    s.offset = profile.offset;
                    s.limit_offset = profile.offset;
                    s.stop_offset = profile.offset;
                    s.te_start = profile.te_start;
                    s.te_step = profile.te_step;
                    s.te_limit = (double)profile.gap_min; 
                    s.ts_start = profile.ts_start; 
                    s.ts_step = profile.ts_step;
                    s.tp = profile.tp;
                    s.sl = profile.sl;

                    if (s.type == 9) s.price_signal = 0;
                    else
                    {
                        if (s.dir == 1) s.price_signal = Math.Round(sMaster.price_signal - (s.offset * point), 2);
                        else if (s.dir == 2) s.price_signal = Math.Round(sMaster.price_signal + (s.offset * point), 2);
                    }

                    s.symbol = s.symbol?.Replace("#", "") ?? string.Empty;
                    s.sid = string.Empty;
                    s.gid = string.Empty;
                    s.Validate();

                    s.args = $"{profile.gno};{profile.type};{s.lot:F2};{(int)profile.offset};{profile.te_start:F1};{profile.te_step:F1};{profile.gap_min};{profile.ts_start};{profile.ts_step};{profile.tp:F1};{profile.sl:F1}";
                    result.Add(s);
                }

                return result;
            }
            catch (Exception ex)
            {
                nlog.Error(ex, $"[Gateway:Option] Error applying options for CNO:{sMaster.cno}");
                sMaster.Validate();
                result.Add(sMaster);
                return result;
            }
        }

        public XDataObject? GetNextSignal()
        {
            if (PendingSignals.IsEmpty) return null;
            var firstKey = PendingSignals.Keys.FirstOrDefault();
            if (firstKey != null && PendingSignals.TryRemove(firstKey, out var xdo))
            {
                SignalRemoved?.Invoke(firstKey);
                return xdo;
            }
            return null;
        }
    }
}

