private static void ConfigureChannels(XParameter param, XConfig config)
{
    nlog.Trace("[Startup] Configuring Channels and Interpreters...");

    foreach (var entry in config.Channels)
    {
        var info = entry.Value;
        if (info.CNO == 0)
        {
            param.RegisterChannel(info);
            continue;
        }

        if (!string.IsNullOrEmpty(info.Plugin.ClassName))
        {
            try
            {
                string fullTypeName = info.Plugin.ClassName.Contains(".")
                    ? info.Plugin.ClassName
                    : FindFullTypeName(info.Plugin.ClassName);

                Type? type = Type.GetType(fullTypeName);
                if (type == null && !string.IsNullOrEmpty(info.Plugin.AssemblyName))
                {
                    fullTypeName = $"{fullTypeName}, {info.Plugin.AssemblyName}";
                    type = Type.GetType(fullTypeName);
                }

                if (type != null)
                {
                    var interpreter = Activator.CreateInstance(type, param, info) as XObject;
                    if (interpreter != null)
                    {
                        param.Add(interpreter);
                        nlog.Trace($"[Startup] Loaded interpreter: {fullTypeName} (CNO:{info.CNO})");
                    }
                }
            }
            catch (Exception ex)
            {
                nlog.Error(ex, $"[Startup] Failed to load interpreter for {info.Name} (CNO:{info.CNO})");
            }
        }
        param.RegisterChannel(info);
    }
}

public static void ConfigureLegacyServices(XParameter param)
{
    nlog.Trace("[Startup] Registering Legacy Core Services...");
    var config = param.Config;

    var db = new XpoSqliteService(param);
    param.Add(db);
    param.Add<ISignalRepository>(db);
    param.Add<IChannelOptionRepository>(db);
    param.Add<IGridProfileRepository>(db);

    param.Add(new XGatewayService(param));
    param.Add(new XSyncWorker(param));
    param.Add(new XTelegram(param));

    LoadOptionsFromConfig(param, config);
}

