using NLog;
using System;
using System.Collections.Generic;
using System.IO;
using System.Text.Json;
using XTA.Channels.GG;
using XTA.Channels.GMK;

using XTA.Infrastructure.Data;
using XTA.Models;
using XTA.Services;
using XTA.Services.TelegramService;
using XTA.XData.Interfaces;
using XTA.XData.Models;

namespace XTA
{
    /// <summary>
    /// XTG 시스템을 초기화 및 서비스를 구성하는 스타트업 클래스
    /// </summary>
    public class XTAStartup
    {
        private static Logger nlog => LogManager.GetCurrentClassLogger();

        /// <summary>
        /// 설정 파일을 로드하여 XParameter 및 서비스들을 초기화합니다.
        /// </summary>
        /// <param name="configPath">XConfig JSON 파일 경로 (기본값: _config/ASTA.json)</param>
        /// <returns>초기화된 XParameter 객체</returns>
        public static XParameter Initialize(string configPath = "_config/ASTA.json")
        {
            // [Fix] 인코딩 프로바이더 등록 (CP949 등 지원)
            System.Text.Encoding.RegisterProvider(System.Text.CodePagesEncodingProvider.Instance);

            // [Fix] 로그 파일 강제 초기화
            string logPath = Path.Combine(AppDomain.CurrentDomain.BaseDirectory, "_log", "XTA_Active.log");
            if (File.Exists(logPath))
            {
                try { File.Delete(logPath); }
                catch { /* 무시 */ }
            }

            var logger = nlog;
            logger.Info($"[Startup] ************************************ {configPath}");
            logger.Info($"[Startup] Initializing XTA System with config: {configPath}");


            // 1. 설정 파일 존재 여부 확인 및 자동 생성
            EnsureConfigFile(configPath);

            // 2. 설정 로드
            XConfig? config = null;
            try
            {
                string json = File.ReadAllText(configPath);
                config = JsonSerializer.Deserialize<XConfig>(json);
            }
            catch (Exception ex)
            {
                nlog.Error(ex, $"[Startup] Failed to load config from {configPath}");
            }

            if (config == null)
            {
                nlog.Fatal("[Startup] Config object is null. Initialization aborted.");
                throw new InvalidOperationException("Config load failed.");
            }

            // 3. XParameter 생성 및 설정 주입
            var param = new XParameter
            {
                Config = config
            };

            // 4. 서비스 및 채널 초기화
            ConfigureServices(param, config);

            nlog.Trace("[Startup] XTA System initialization completed.");
            return param;
        }
        private static void ConfigureServices(XParameter param, XConfig config)
        {
            nlog.Trace("[Startup] Configuring Services and Channels from Config (Dynamic)...");

            // 1. 설정된 모든 채널을 순회하며 인터프리터 동적 생성
            foreach (var entry in config.Channels)
            {
                var info = entry.Value;
                if (info.CNO == 0)
