        /// </summary>
        public static void Start(XParameter param)
        {
            nlog.Trace("[Startup] Starting all registered services...");
            param.StartAll();

            // [Phase 2] 앱 재시작 시 티켓-SID 매핑 캐시 재구축
            try
            {
                var repo = param.GetService<ISignalRepository>();
                if (repo != null)
                {
                    // 비동기 실행을 위해 Task.Run 사용 (UI 스레드 차단 방지)
                    Task.Run(async () =>
                    {
                        var activeSignals = await repo.GetAllActiveSignalsAsync();
                        XTradeManager.Instance.Initialize(activeSignals);
                        nlog.Info($"[Startup] Rebuilt XTradeManager ticket-SID mapping cache: {activeSignals.Count} signals loaded.");
