                channels["-1001658145217"] = CreateTradeChannel(-1001658145217, 1002, "GMK", "GMK");
                channels["-1000000002001"] = CreateTradeChannel(-1000000002001, 2001, "LFT", "GMK");
                channels["-1000000002002"] = CreateTradeChannel(-1000000002002, 2002, "MM", "GMK");
                channels["-1003778889507"] = CreateTradeChannel(-1003778889507, 3001, "HANA", "GlobalGold");
                channels["-1003697953708"] = CreateTradeChannel(-1003697953708, 3002, "DUNA", "GMK");
                string appData = Environment.GetFolderPath(Environment.SpecialFolder.ApplicationData);
                string commonPath = Path.Combine(appData, @"MetaQuotes\Terminal\Common\Files");

                var defaultConfig = new XConfig
                {
                    Version = "1.0.0",
                    SystemSettings = new XSystemSettings
                    {
                        Paths = new XPathSettings
                        {
                            ProdDbFullpath = Path.Combine(commonPath, "XTA.db"),
                            TestDbFullpath = Path.Combine(commonPath, "XTA_TEST.db"),
