                            EnableAllChannelLogs = true
                        },
                        Window = new XWindowSettings
                        {
                            Left = 100,
                            Top = 100,
                            Width = 1650,
                            Height = 900
                        }
                    },
                    Channels = channels
                };

                try
                {
                    var options = new JsonSerializerOptions { WriteIndented = true };
                    string defaultJson = JsonSerializer.Serialize(defaultConfig, options);
