using DevExpress.Data.Filtering;
using DevExpress.Mvvm;
using DevExpress.Xpo;
using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using XTA.Infrastructure.Data;
using XTA.XData.Interfaces;
using XTA.XData.Models;
using XTA.Models;
using XTA.Extensions;
using FluentSeq;

namespace XTA.Services
{
    /// <summary>
    /// 누락된 메시지 복구 및 동기화를 담당하는 워커
    /// </summary>
    public class XSyncWorker : XObject
    {
        private Timer? _syncTimer;
        private readonly int _intervalSeconds = 10;
        private readonly int _lookbackMinutes = 60;
        private readonly int _maxRetryCount = 5;
        private int _isBusyInt = 0;

        private ISequence<string> _syncSeq = null!;
        private SyncContext? _ctx;

        public XSyncWorker(XParameter param) : base(param) { InitSequence(); }

        private void InitSequence()
        {
            _syncSeq = new FluentSeq<string>()
                .Create("Idle")
                // [Log Level Optimization] 주기적(10초)으로 발생하는 백그라운드 워커의 상태 전이 로그(Idle/Prepare/Query) 출력을 억제하기 위해 자동 디버그 로깅 비활성화
                // .ActivateDebugLogging(nlog) 
                .ConfigureState("Idle")
                .ConfigureState("Prepare")
                    .OnEntry(() => {
                        _ctx = new SyncContext();
                        var db = param.GetService<XpoSqliteService>();
                        if (db == null) { _syncSeq.SetState("Idle"); return; }
                        _ctx.DbService = db;
                        _ctx.TradeCnos = param.Config.Channels.Values.Where(c => c.Type.Equals("TRADE", StringComparison.OrdinalIgnoreCase)).Select(c => c.CNO).ToList();
                        if (_ctx.TradeCnos.Count == 0) _syncSeq.SetState("Idle");
                    })
                .ConfigureState("Query")
                    .OnEntry(() => {
                        if (_ctx?.DbService == null) return;
                        using var uow = new UnitOfWork(_ctx.DbService.GetLayer());
                        var lookback = DateTime.Now.AddMinutes(-_lookbackMinutes);
                        var criteria = CriteriaOperator.And(new InOperator("CNO", _ctx.TradeCnos), CriteriaOperator.Parse("Status IN (0, 2) AND Time > ? AND RetryCount < ?", lookback, _maxRetryCount));
                        _ctx.PendingMessages = new XPCollection<XpoTgMessage>(uow, criteria).ToList();
                        if (_ctx.PendingMessages.Count == 0) _syncSeq.SetState("Idle");
                    })
                .ConfigureState("Recover")
                    .OnEntry(() => {
                        if (_ctx?.DbService == null || _ctx.PendingMessages.Count == 0) return;
                        nlog.Info($"[SyncWorker] Found {_ctx.PendingMessages.Count} unprocessed messages. Recovering...");
                        using var uow = new UnitOfWork(_ctx.DbService.GetLayer());
                        foreach (var msgXpo in _ctx.PendingMessages)
                        {
                            var msg = uow.GetObjectByKey<XpoTgMessage>(msgXpo.Oid);
                            if (msg == null) continue;
                            if (uow.FindObject<XpoSignal>(CriteriaOperator.Parse("msg_id = ?", msg.Oid)) != null) { msg.Status = 1; continue; }

                            messenger.Send(new XDataObject { CID = msg.CID, CNO = msg.CNO, Text = msg.Text, Timestamp = msg.Time, MsgId = msg.Oid, CMD = "RECOVERY_SYNC" }, "MSG_TO_INTERPRET");
                            msg.RetryCount++;
                            msg.Status = (msg.RetryCount >= _maxRetryCount) ? 3 : 2;
                        }
                        uow.CommitChanges();
                    })
                .Builder().DisableValidation().Build();
        }

        public override void Start()
        {
            _syncTimer = new Timer(OnSyncTimerCallback, null, TimeSpan.FromSeconds(5), TimeSpan.FromSeconds(_intervalSeconds));
            nlog.Trace($"[SyncWorker] Started (Interval: {_intervalSeconds}s)");
        }

        public override void Stop() { _syncTimer?.Dispose(); nlog.Trace("[SyncWorker] Stopped."); }

        private async void OnSyncTimerCallback(object? state)
        {
            if (Interlocked.CompareExchange(ref _isBusyInt, 1, 0) != 0) return;
            try { await Task.Run(() => ProcessSync()); }
            catch (Exception ex) { nlog.Error(ex, "[SyncWorker] Sync Error"); }
            finally { Interlocked.Exchange(ref _isBusyInt, 0); }
        }

        private void ProcessSync()
        {
            string[] steps = { "Prepare", "Query", "Recover" };
            foreach (var step in steps) { _syncSeq.SetState(step); _syncSeq.Run(); if (_syncSeq.IsInState("Idle")) break; }
        }

        private class SyncContext { public XpoSqliteService? DbService { get; set; } public List<int> TradeCnos { get; set; } = new(); public List<XpoTgMessage> PendingMessages { get; set; } = new(); }
    }
}

using System;
using System.Collections.Generic;
using System.Linq;
using System.Threading.Tasks;
using TL;
using XTA.Models;
using XTA.Core;

namespace XTA.Services.TelegramService
{
    public class XTelegram : XTelegramBase
    {
        /// <summary>
        /// 텔레그램 메시지 수신 시 발생하는 이벤트 (UI 대시보드 로그용)
        /// </summary>
        public event Action<XDataObject>? MessageReceived;

        public XTelegram(XParameter param) : base(param)
        {
        }

        public override void Start()
        {
            base.Start();
            nlog?.Trace("[XTelegram] Service class specific Start completed.");
        }

        public override void ProcessSignal(XDataObject xdo)
        {
            if (xdo == null || xdo.CID != this.CID) return;
            nlog?.Trace($"[SIGNAL_PROCESS] CID:{CID} Received Signal Context: {xdo.Text}");
        }

        protected override Task HandleUpdate(UpdatesBase updates)
        {
            if (updates == null) return Task.CompletedTask;

            foreach (var update in updates.UpdateList)
            {
                TL.Message? msg = null;

                if (update is UpdateNewChannelMessage uncm && uncm.message is TL.Message m1) msg = m1;
                else if (update is UpdateNewMessage unm && unm.message is TL.Message m2) msg = m2;

                if (msg == null) continue;

                long rawId = msg.peer_id.ID;
                long peerId = rawId;

                string channelTitle = "Unknown";
                if (updates.Chats.TryGetValue(rawId, out var chat)) channelTitle = chat.Title ?? "Unknown";

                nlog.Trace($"[TG:DEBUG] Incoming Update: PeerID:{rawId} (Title:\"{channelTitle}\") | MsgId:{msg.id}");

                if (!param.Channels.ContainsKey(peerId))
                {
                    var matchedInfo = param.Channels.Values.FirstOrDefault(c =>
                        c.CID == rawId ||
                        Math.Abs(c.CID % 10000000000L) == Math.Abs(rawId % 10000000000L) ||
                        (uint)c.CID == (uint)rawId ||
                        (int)c.CID == (int)rawId
                    );

                    if (matchedInfo != null)
                    {
                        peerId = matchedInfo.CID;
                        nlog.Info($"[SIGNAL:STEP-0:MATCH] PeerID {rawId} fuzzy-matched to Registered CID {peerId} ({matchedInfo.Name})");
                    }
                    else
                    {
                        continue;
                    }
                }
                string summary = msg.message.Replace("\n", " ");
                if (summary.Length > 50) summary = summary.Substring(0, 50) + "...";

                nlog.Info($"[SIGNAL:STEP-0:RECEIVE] TG Update Detected. MsgId:{msg.id} | RawPeer:{rawId} (\"{channelTitle}\") | Text:{summary}");

                var info = param.GetChannel(peerId);
                if (info == null) continue;

                nlog.Info($"[SIGNAL:STEP-0:ACCEPT] CID:{peerId} | CNO:{info.CNO} | Name:{info.Name} | MsgId:{msg.id}");

                XDataObject xdo = new XDataObject()
                {
                    Sender = this.GetType().Name,
                    CID = peerId,
                    Text = msg.message,
                    CName = channelTitle,
                    CNO = info.CNO,
                    Timestamp = msg.date,
                    MsgId = msg.id
                };

                try
                {
                    // 1. 게이트웨이 서비스로 직접 전송
                    XContext.Instance.Gateway?.EnqueueRawMessage(xdo);
                    nlog.Info($"[SIGNAL:STEP-0:DISPATCH] Dispatched MsgId:{msg.id} to Gateway Service.");

                    // 2. 외부(UI 등) 구독자에게 알림 (구 DashboardChannel 대체)
                    MessageReceived?.Invoke(xdo);
                    nlog.Info($"[SIGNAL:STEP-0:DASHBOARD] Broadcasted TG message event for CNO:{info.CNO}");
                }
                catch (Exception ex)
                {
                    nlog.Error(ex, $"[TG:DISPATCH] Dispatch Error. MsgId:{msg.id}");
                }
            }

            return Task.CompletedTask;
        }
    }
}

