                        var criteria = CriteriaOperator.And(new InOperator("CNO", _ctx.TradeCnos), CriteriaOperator.Parse("Status IN (0, 2) AND Time > ? AND RetryCount < ?", lookback, _maxRetryCount));
                        _ctx.PendingMessages = new XPCollection<XpoTgMessage>(uow, criteria).ToList();
                        if (_ctx.PendingMessages.Count == 0) _syncSeq.SetState("Idle");
                    })
                .ConfigureState("Recover")
                    .OnEntry(() => {
                        if (_ctx?.DbService == null || _ctx.PendingMessages.Count == 0) return;
                        nlog.Info($"[SyncWorker] Found {_ctx.PendingMessages.Count} unprocessed messages. Recovering...");
                        using var uow = new UnitOfWork(_ctx.DbService.GetLayer());
                        foreach (var msgXpo in _ctx.PendingMessages)
                        {
                            var msg = uow.GetObjectByKey<XpoTgMessage>(msgXpo.Oid);
                            if (msg == null) continue;
                            if (uow.FindObject<XpoSignal>(CriteriaOperator.Parse("msg_id = ?", msg.Oid)) != null) { msg.Status = 1; continue; }

                            var xdo = new XDataObject { CID = msg.CID, CNO = msg.CNO, Text = msg.Text, Timestamp = msg.Time, MsgId = msg.Oid, CMD = "RECOVERY_SYNC" };
                            XContext.Instance.Gateway?.EnqueueRawMessage(xdo);

                            msg.RetryCount++;
                            msg.Status = (msg.RetryCount >= _maxRetryCount) ? 3 : 2;
                        }
                        uow.CommitChanges();
                    })
                .Builder().DisableValidation().Build();
        }

        public override void Start()
        {
            _syncTimer = new Timer(OnSyncTimerCallback, null, TimeSpan.FromSeconds(5), TimeSpan.FromSeconds(_intervalSeconds));
            nlog.Trace($"[SyncWorker] Started (Interval: {_intervalSeconds}s)");
        }

        public override void Stop() { _syncTimer?.Dispose(); nlog.Trace("[SyncWorker] Stopped."); }

        private async void OnSyncTimerCallback(object? state)
        {
            if (Interlocked.CompareExchange(ref _isBusyInt, 1, 0) != 0) return;
            try { await Task.Run(() => ProcessSync()); }
            catch (Exception ex) { nlog.Error(ex, "[SyncWorker] Sync Error"); }
            finally { Interlocked.Exchange(ref _isBusyInt, 0); }
        }

        private void ProcessSync()
        {
            string[] steps = { "Prepare", "Query", "Recover" };
            foreach (var step in steps) { _syncSeq.SetState(step); _syncSeq.Run(); if (_syncSeq.IsInState("Idle")) break; }
        }

        private class SyncContext { public XpoSqliteService? DbService { get; set; } public List<int> TradeCnos { get; set; } = new(); public List<XpoTgMessage> PendingMessages { get; set; } = new(); }
    }
}

