using DevExpress.Mvvm;
using NLog;
using System;
using System.IO;
using XTA.Models;
using XTA.XData.Models;
using XSignal = XTA.Models.XSignal;
using FluentSeq;

namespace XTA.Infrastructure.Audio
{
    /// <summary>
    /// TTS 출력을 총괄하는 서비스 (MP3 제거 및 TTS 단일화 v6.0)
    /// </summary>
    public class XSoundService : XChannelObject
    {
        private readonly object _spamLock = new();
        private string _lastSid = string.Empty;
        private string _lastEvent = string.Empty;
        private DateTime _lastPlayTime = DateTime.MinValue;

        private ISequence<SoundState> _sequence = null!;
        private XDataObject? _currentXdo;
        private string _currentTtsMsg = string.Empty;

        public XSoundService(XParameter param) : base(param, new XChannelInfo(0, 0, "SOUND_SERVICE", "SYSTEM"))
        {
            nlog = LogManager.GetLogger(GetType().FullName ?? "XTA.TTS.XSoundService");

            InitSequence();
        }

        private void InitSequence()
        {
            _sequence = new FluentSeq<SoundState>()
                .Create(SoundState.RequestReceived)
                .ActivateDebugLogging(nlog)

                // 1. 초기 상태: 요청 수신
                .ConfigureState(SoundState.RequestReceived)

                // 2. 메시지 조립 상태
                .ConfigureState(SoundState.Composed)
                    .TriggeredBy(() => _currentXdo?.Signal != null && !string.IsNullOrEmpty(_currentXdo.CMD))
                        .WhenInState(SoundState.RequestReceived)
                    .OnEntry(() => {
                        UpdateSpamInfo(_currentXdo!.Signal!.sid, _currentXdo.CMD!);

                        // [v5.5] 전달받은 텍스트가 있으면 우선 사용, 없으면 자동 생성
                        if (string.IsNullOrEmpty(_currentXdo.Text))
                        {
                            _currentTtsMsg = GetTtsMessage(_currentXdo.Signal, _currentXdo.CMD!);
                        }
                        else
                        {
                            _currentTtsMsg = _currentXdo.Text;
                        }
                    })

                // 3. 완료 상태 (직접 요청 및 조립된 메시지 발화)
                .ConfigureState(SoundState.Completed)
                    .TriggeredBy(() => _currentXdo != null && !string.IsNullOrEmpty(_currentXdo.Text))
                        .WhenInState(SoundState.RequestReceived)
                    .TriggeredBy(() => !string.IsNullOrEmpty(_currentTtsMsg))
                        .WhenInState(SoundState.Composed)
                    .OnEntry(() => {
                        if (!string.IsNullOrEmpty(_currentTtsMsg))
                        {
                            nlog.Debug($"[SoundService] Payload Based TTS: {_currentTtsMsg} (CMD={_currentXdo?.CMD})");
                            var sidLogger = LogManager.GetLogger($"XTX_{DateTime.Now:yyyyMMdd}_{_currentXdo?.Signal?.sid}");
                            sidLogger.Info($"[SOUND:TTS] {_currentTtsMsg} (CMD={_currentXdo?.CMD})");
                            messenger.Send(new XDataObject { Text = _currentTtsMsg }, "TTS_SPEAK_REQ");
                        }
                        else if (_currentXdo != null && !string.IsNullOrEmpty(_currentXdo.Text))
                        {
                            nlog.Debug($"[SoundService] Direct Text TTS Request: {_currentXdo.Text}");
                            messenger.Send(new XDataObject { Text = _currentXdo.Text }, "TTS_SPEAK_REQ");
                        }
                    })

                // 4. 억제 상태 (필터링)
                .ConfigureState(SoundState.Suppressed)
                    .TriggeredBy(() => _currentXdo?.Signal != null && IsSpam(_currentXdo.Signal.sid, _currentXdo.CMD))
                        .WhenInState(SoundState.RequestReceived)
                    .TriggeredBy(() => _currentXdo?.Signal != null && !IsTargetChannel(_currentXdo.Signal.cno))
                        .WhenInState(SoundState.RequestReceived)
                    .TriggeredBy(() => _currentXdo?.Signal?.xe_status == (int)XCode.EaStatus.ExecutingMarket) // [v6.1] 시장가 체결 중(xe_status=6) 사운드 출력 제외
                        .WhenInState(SoundState.RequestReceived)
                    .OnEntry(() => {
                        if (_currentXdo?.Signal != null && IsSpam(_currentXdo.Signal.sid, _currentXdo.CMD)) {
                            nlog.Trace($"[SoundService] Anti-Spam: Skipping duplicate sound for SID:{_currentXdo.Signal.sid} CMD:{_currentXdo.CMD}");
                        }
                        if (_currentXdo?.Signal?.xe_status == (int)XCode.EaStatus.ExecutingMarket)
                        {
                            nlog.Trace($"[SoundService] Suppressed: Skipping sound for XE_EXECUTING_MARKET (xe_status=6) | SID:{_currentXdo.Signal.sid}");
                        }
                    })

                .Builder()
                .DisableValidation()
                .Build();
        }

        public override void Start()
        {
            messenger.Register<XDataObject>(this, "SOUND_PLAY_REQ", true, OnSoundPlayRequest);
            nlog.Trace("[SoundService] Service Started.");
        }

        public override void Stop()
        {
            messenger.Unregister(this);
            nlog.Trace("[SoundService] Service Stopped.");
        }

        private void OnSoundPlayRequest(XDataObject xdo)
        {
            if (xdo == null) return;

            _currentXdo = xdo;
            _currentTtsMsg = string.Empty;

            _sequence.SetState(SoundState.RequestReceived);

            // 시퀀스가 완료 상태에 도달할 때까지 실행 (최대 3회 반복으로 무한 루프 방지)
            int safetyCounter = 0;
            while (!_sequence.IsInState(SoundState.Completed) && 
                   !_sequence.IsInState(SoundState.Suppressed) && 
                   safetyCounter++ < 3)
            {
                _sequence.Run();
            }
        }

        private bool IsSpam(string sid, string? cmd)
        {
            lock (_spamLock)
            {
                return sid == _lastSid && cmd == _lastEvent && (DateTime.Now - _lastPlayTime).TotalSeconds < 2;
            }
        }

        private void UpdateSpamInfo(string sid, string cmd)
        {
            lock (_spamLock)
            {
                _lastSid = sid;
                _lastEvent = cmd;
                _lastPlayTime = DateTime.Now;
            }
        }

        private string GetTtsMessage(XSignal sig, string eventType)
        {
            string cnoStr = GetDigitString(sig.cno);
            // [v5.1] 방향 판별 강화: 1=매수, 2=매도 (XCode.SELL=2 명시적 처리)
            string dirName = (sig.dir == 2) ? "매도" : "매수"; 

            return eventType switch
            {
                //"TELEGRAM_RECEIVED" => "새로운 텔레그램 메시지가 수신되었습니다.",
                "SIGNAL_RECEIVED" => $"{cnoStr} 채널 {sig.sno}회차 {dirName} 신호 발생",
                "ORDER_PLACED" => $"{cnoStr} 채널 {sig.sno}회차 {dirName} 주문 접수 완료",
                "POSITION_ENTERED" => $"{cnoStr} 채널 {sig.sno}회차 {dirName} 진입 완료",
                "POSITION_CLOSED" => $"{cnoStr} 채널 {sig.sno}회차 {dirName} 청산 완료",
                "GROUP_CLOSE" => $"{cnoStr} 채널 그룹 청산 명령 발생",
                "SID_CLOSE" => $"{cnoStr} 채널 {sig.sno}회차 개별 청산 명령 발생",
                "TE_TRIGGERED" => $"{cnoStr} 채널 {dirName} 진입 추적 가동",
                "CLOSE_STRATEGY_STARTED" => $"{cnoStr} 채널 {sig.sno}회차 청산 전략이 가동되었습니다.",
                _ => string.Empty
            };
        }

        private string GetDigitString(int value)
        {
            string s = value.ToString();
            string result = "";
            foreach (char c in s)
            {
                result += c switch
                {
                    '0' => "영 ",
                    '1' => "일 ",
                    '2' => "이 ",
                    '3' => "삼 ",
                    '4' => "사 ",
                    '5' => "오 ",
                    '6' => "육 ",
                    '7' => "칠 ",
                    '8' => "팔 ",
                    '9' => "구 ",
                    _ => c + " "
                };
            }
            return result.Trim();
        }

        private bool IsTargetChannel(int cno)
        {
            var channel = param.GetChannelByCno(cno);
            if (channel == null) 
            {
                nlog.Warn($"[SoundService] Channel CNO:{cno} not found in config. Suppressing sound.");
                return false;
            }
            if (!channel.IsSoundEnabled)
            {
                nlog.Trace($"[SoundService] Sound suppressed for CNO:{cno} (IsSoundEnabled=false)");
                return false;
            }
            return true;
        }
    }
}

