        private readonly SpeechSynthesizer _synth = new();
        private readonly BlockingCollection<string> _speechQueue = new();
        private readonly CancellationTokenSource _cts = new();

        public XTtsService(XParameter param) : base(param, new XChannelInfo(0, 0, "TTS_SERVICE", "SYSTEM"))
        {
            // 한국어 음성 설정 시도
            try
            {
                var voices = _synth.GetInstalledVoices();
                foreach (var voice in voices)
                {
                    if (voice.VoiceInfo.Culture.Name.Contains("ko"))
                    {
                        _synth.SelectVoice(voice.VoiceInfo.Name);
                        break;
                    }
                }
                _synth.Rate = 1; // 속도 (0~2)
                _synth.Volume = 100; // 볼륨 (0~100)
            }
            catch { }

            // [v8.9] 큐 기반 순차 출력 워커 시작
            Task.Run(() => ProcessQueue(_cts.Token));
        }

        public override void Start()
        {
            messenger.Register<XDataObject>(this, "TTS_SPEAK_REQ", true, OnTtsRequest);
            nlog.Trace("[TTS] XTtsService Started (Queue Worker Active).");
        }

        public override void Stop()
        {
            messenger.Unregister(this);
            _cts.Cancel();
            _speechQueue.CompleteAdding();

            try
            {
                _synth.SpeakAsyncCancelAll();
                _synth.Dispose();
            }
            catch { }

            nlog.Trace("[TTS] XTtsService Stopped and Disposed.");
        }

        private void OnTtsRequest(XDataObject xdo)
        {
            if (string.IsNullOrEmpty(xdo.Text)) return;
            nlog.Debug($"[TTS] Speak Request Received: {xdo.Text}");
            Speak(xdo.Text);
        }

        public void Speak(string text)
        {
            if (string.IsNullOrEmpty(text) || _speechQueue.IsAddingCompleted) return;

            try
            {
                _speechQueue.Add(text);
                nlog.Trace($"[TTS] Enqueued: {text} (Queue Size: {_speechQueue.Count})");
            }
            catch (Exception ex)
            {
                nlog.Error(ex, "[TTS] Error while enqueuing speech text.");
            }
        }

        private void ProcessQueue(CancellationToken token)
        {
            nlog.Info("[TTS:Worker] Speech worker thread started.");

            try
            {
                foreach (var text in _speechQueue.GetConsumingEnumerable(token))
                {
                    try
                    {
                        nlog.Debug($"[TTS:Worker] >>> Starting Speech: {text}");
                        // Speak는 동기 메서드이므로 출력이 완료될 때까지 이 스레드는 블록됨 (순서 보장 핵심)
                        _synth.Speak(text);
                        nlog.Debug($"[TTS:Worker] <<< Finished Speech: {text}");
                    }
                    catch (OperationCanceledException) { break; }
                    catch (Exception ex)
                    {
                        nlog.Error(ex, $"[TTS:Worker] Error during speech output: {text}");
                    }
                }
            }
            catch (OperationCanceledException) { }
            finally
            {
                nlog.Info("[TTS:Worker] Speech worker thread terminated.");
            }
        }
    }
}
